const plannerRes = $('Planner Agent').item.json;

let selected = "default";
let requiresRag = false;

try {
  const text = plannerRes.text;
  const cleanText = text.replace(/```json/gi, "").replace(/```/gi, "").trim();
  const parsed = JSON.parse(cleanText);
  selected = parsed.selected_agent || "default";
  requiresRag = (parsed.requires_rag === true || parsed.requires_rag === "true");
} catch (e) {
  selected = "default";
  requiresRag = false;
}

return {
  selected_agent: selected,
  requires_rag: requiresRag
};

const retrievalData = $('Call Python Retrieval API').first().json;
const results = (retrievalData.results || []).filter(r => r.distance < 1.3);

const contextTexts = [];
const citations = [];
let retrievalFailed = false;

if (results.length === 0) {
  retrievalFailed = true;
} else {
  results.forEach((chunk, index) => {
    const meta = chunk.metadata || {};
    const physPage = meta.physical_page;
    const pdfPage = meta.pdf_page_number || (meta.pdf_page_index !== undefined ? meta.pdf_page_index + 1 : undefined);
    const pageStr = (physPage !== undefined && physPage !== -1) ? `Trang ${physPage}` : (pdfPage !== undefined ? `Trang PDF ${pdfPage}` : 'Trang chưa rõ');
    const lessonName = meta.lesson_name || 'Chưa rõ';
    const fileName = meta.file_name || 'SGK Toán 3';
    const volume = meta.volume || '1';
    contextTexts.push(`--- Đoạn ${index + 1}: ${fileName}, ${pageStr} ---\n${chunk.text}`);
    citations.push(`- **Tài liệu:** ${fileName} | **Bài học:** ${lessonName} | **Vị trí:** ${pageStr} (Tập ${volume})`);
  });
}

return {
  joined_context: contextTexts.join('\n\n'),
  citation_block: citations.join('\n'),
  retrieval_failed: retrievalFailed
};

let joinedContext = "";
let citationBlock = "";
let retrievalFailed = false;

const plannerNode = $('Parse Planner Decision').first().json;
const selectedAgent = plannerNode.selected_agent;
const requiresRag = plannerNode.requires_rag;

if (requiresRag) {
  try {
    const processNode = $('Process Retrieval Results').first().json;
    joinedContext = processNode.joined_context;
    citationBlock = processNode.citation_block;
    retrievalFailed = (processNode.retrieval_failed === true || processNode.retrieval_failed === "true");
  } catch (e) {
    joinedContext = "";
    citationBlock = "";
    retrievalFailed = true;
  }
}

const securityNode = $('Security & Sanitization Gate').first().json.body;
const userPrompt = securityNode.prompt;
const overrides = securityNode.prompt_overrides || {};

let activePrompts = {};
try {
  activePrompts = $('Fetch Active Prompts').first().json;
} catch (e) {
  activePrompts = {};
}

const getPrompt = (agentName, defaultVal) => {
  return overrides[agentName] || activePrompts[agentName] || defaultVal;
};

let finalAgent = selectedAgent;
let finalRequires = requiresRag;
if (securityNode.agent_mode && securityNode.agent_mode !== "default" && securityNode.agent_mode !== "") {
  finalAgent = securityNode.agent_mode;
  if (securityNode.agent_mode !== "default") {
    finalRequires = true;
  }
}

const RAG_FALLBACK = "⚠️ Rất tiếc, trong các trang SGK được trích xuất hiện tại không có thông tin hoặc bài học giải thích cho câu hỏi này.";
const RAG_RULE_PREFIX = "QUY TẮC BẮT BUỘC KHÔNG ĐƯỢC VI PHẠM (STRICT GROUNDED RAG):\nNếu Ngữ cảnh tài liệu SGK KHÔNG CHỨA thông tin cần thiết, BẮT BUỘC trả lời chính xác: \"" + RAG_FALLBACK + "\" và KHÔNG in phần trích dẫn nguồn.\
\
Ngữ cảnh tài liệu SGK:\
" + joinedContext + "\
\
";

// --- Default Teacher ---
let defaultTeacherPrompt = "";
const baseDefaultTeacher = getPrompt('default_teacher', 'Bạn là một giáo viên tiểu học thân thiện, tận tụy và dịu dàng.');
if (finalRequires) {
  defaultTeacherPrompt = baseDefaultTeacher + "\n\n" + RAG_RULE_PREFIX +
    "Câu hỏi của người dùng:\n" + userPrompt +
    "\n\nYêu cầu định dạng câu trả lời (chỉ khi Ngữ cảnh SGK CÓ chứa câu trả lời):\n1. Trả lời thân thiện, giải thích từng bước logic toán học rõ ràng.\n2. Trả lời hoàn toàn bằng tiếng Việt.\n3. Cuối câu trả lời, in rõ phần trích dẫn nguồn theo đúng định dạng sau:\n\n---\n📖 **Nguồn tham khảo:**\n" + citationBlock;
} else {
  defaultTeacherPrompt = baseDefaultTeacher + " Hãy trò chuyện thân thiện, trả lời tự nhiên hoặc giải thích toán học đơn giản cho câu hỏi của người dùng.\n\nCâu hỏi/Lời nhắn của người dùng:\n" + userPrompt + "\n\nYêu cầu:\n1. Trả lời thân thiện, ngọt ngào bằng tiếng Việt.\n2. Không cần trích dẫn nguồn sách giáo khoa.";
}

// --- Barem Reviewer ---
const baseBarem = getPrompt('barem_review', 'Bạn là một giáo viên tiểu học thân thiện, tận tụy và công tâm. Nhiệm vụ của bạn là chấm điểm và nhận xét bài làm của học sinh tiểu học (lớp 3) dựa trên Barem điểm và đáp án chuẩn được cung cấp.');
const baremPrompt = baseBarem + "\n\n" + RAG_RULE_PREFIX +
  "Câu hỏi/Yêu cầu chấm điểm (chứa Đề bài, Barem & Bài làm của học sinh):\n" + userPrompt +
  "\n\nHãy thực hiện chấm điểm và đưa ra nhận xét sư phạm chi tiết, ấm áp.\n\n---\n📖 **Nguồn tham khảo:**\n" + citationBlock;

// --- Theory Explainer ---
const baseTheory = getPrompt('theory_explanation', 'Bạn là một giáo viên tiểu học có tài giảng dạy trực quan, sinh động. Nhiệm vụ của bạn là giải thích các định nghĩa, khái niệm toán học lớp 3 từ sách giáo khoa một cách dễ hiểu nhất.');
const theoryPrompt = baseTheory + "\n\n" + RAG_RULE_PREFIX +
  "Câu hỏi của học sinh/phụ huynh về khái niệm lý thuyết:\n" + userPrompt +
  "\n\nGiải thích trực quan, gần gũi, dùng ví dụ thực tế cho trẻ em 8-9 tuổi.\n\n---\n📖 **Nguồn tham khảo:**\n" + citationBlock;

// --- Exercise Generator ---
const baseExercise = getPrompt('exercise_generator', 'Bạn là một chuyên gia biên soạn tài liệu toán tiểu học. Nhiệm vụ của bạn là tạo ra các bài tập tự luyện mới dựa trên ngữ cảnh bài học trong sách giáo khoa.');
const exercisePrompt = baseExercise + "\n\n" + RAG_RULE_PREFIX +
  "Yêu cầu tạo bài tập của người dùng:\n" + userPrompt +
  "\n\nTạo bộ bài tập 3 mức độ (Nhận biết, Vận dụng, Vận dụng cao) phù hợp với học sinh lớp 3.\n\n---\n📖 **Dựa trên bài học nguồn:**\n" + citationBlock;

// --- Suggestive Tutor ---
const baseTutor = getPrompt('suggestive_tutor', 'Bạn là một Gia sư Toán Tiểu học có phương pháp dạy học tương tác, gợi mở (Socratic method). TUYỆT ĐỐI KHÔNG đưa ra lời giải đầy đủ hay đáp số cuối cùng ngay lập tức. Hãy dắt tay học sinh tự tìm ra đáp án.');
const tutorPrompt = baseTutor + "\n\n" + RAG_RULE_PREFIX +
  "Câu hỏi cần gợi ý của học sinh:\n" + userPrompt +
  "\n\nHướng dẫn từng bước bằng câu hỏi gợi mở, không đưa đáp số trực tiếp.";

// --- Direct Solver ---
const baseSolver = getPrompt('direct_solver', 'Bạn là một Trợ lý Giải Toán Tiểu học nhanh chóng và chính xác. Nhiệm vụ của bạn là đưa ra kết quả cuối cùng ngay lập tức, sau đó trình bày bài giải chi tiết theo đúng chuẩn sư phạm lớp 3.');
const solverPrompt = baseSolver + "\n\n" + RAG_RULE_PREFIX +
  "Câu hỏi/Bài toán cần giải:\n" + userPrompt +
  "\n\n🎯 Đưa ra đáp số nhanh trước, sau đó trình bày từng bước giải chi tiết.\n\n---\n📖 **Nguồn tham khảo:**\n" + citationBlock;

return {
  prompt: userPrompt,
  joined_context: joinedContext,
  citation_block: citationBlock,
  selected_agent: finalAgent,
  requires_rag: finalRequires,
  retrieval_failed: retrievalFailed,
  default_teacher_prompt: defaultTeacherPrompt,
  barem_prompt: baremPrompt,
  theory_prompt: theoryPrompt,
  exercise_prompt: exercisePrompt,
  tutor_prompt: tutorPrompt,
  solver_prompt: solverPrompt
};

const verifierRes = $('Verifier QA Agent').first().json;
const draftResponse = $('Aggregate Expert Draft').first().json.draft_response;

let outputText = "";
try {
  const text = verifierRes.text;
  const cleanText = text.replace(/```json/gi, "").replace(/```/gi, "").trim();
  const parsed = JSON.parse(cleanText);

  if (parsed.status === "APPROVED") {
    outputText = draftResponse;
  } else {
    outputText = parsed.corrected_response || draftResponse;
  }
} catch (e) {
  outputText = draftResponse;
}

const securityNode = $('Security & Sanitization Gate').first().json.body;
const overrides = securityNode.prompt_overrides || {};

let activePrompts = {};
try {
  activePrompts = $('Fetch Active Prompts').first().json;
} catch (e) {
  activePrompts = {};
}

const getPrompt = (agentName, defaultVal) => {
  return overrides[agentName] || activePrompts[agentName] || defaultVal;
};

const baseVerifier = getPrompt('verifier', 'Bạn là một Giáo sư/Chuyên gia Kiểm định Chất lượng Giáo dục Tiểu học.');

const mergeNode = $('Merge Context Nodes').first().json;
const requiresRag = mergeNode.requires_rag;
const selectedAgent = mergeNode.selected_agent || 'default';

// --- INTENT-AWARE VERIFIER PROMPT ---
let verifierPrompt = "";

if (!requiresRag) {
  // Intent: social chat / general question — no RAG grounding needed
  verifierPrompt = "Bạn là một chuyên gia kiểm định chất lượng phản hồi của giáo viên tiểu học.\n\n" +
    "**Loại câu hỏi:** Trò chuyện xã giao / câu hỏi tổng quát (KHÔNG cần tra cứu sách giáo khoa).\n\n" +
    "Câu hỏi/Lời nhắn của người dùng:\n" + mergeNode.prompt + "\n\n" +
    "Phản hồi nháp của Giáo viên:\n" + draftResponse + "\n\n" +
    "QUY TẮC ĐÁNH GIÁ (cho loại trò chuyện xã giao):\n" +
    "1. Phản hồi có thân thiện, ấm áp, phù hợp với vai trò giáo viên tiểu học không?\n" +
    "2. Phản hồi có đáp lại đúng ý định/nội dung câu hỏi của người dùng không?\n" +
    "3. Phản hồi có tự nhiên, không cứng nhắc hay máy móc không?\n" +
    "4. KHÔNG cần kiểm tra grounding SGK — đây là cuộc trò chuyện thông thường.\n" +
    "5. Nếu phản hồi phù hợp và thân thiện → APPROVED. Nếu có điều chỉnh nhỏ cần thiết → CORRECTED.\n\n" +
    "Định dạng đầu ra bắt buộc (JSON):\n" +
    "{\n  \"status\": \"APPROVED\" | \"CORRECTED\",\n  \"reason\": \"Giải thích ngắn gọn\",\n  \"corrected_response\": \"Phản hồi đã chỉnh sửa (chỉ khi CORRECTED)\"\n}";
} else {
  // Intent: math/textbook question — full RAG grounding check required
  const agentLabel = {
    'suggestive_tutor': 'Gia sư Gợi mở (Suggestive Tutor)',
    'direct_solver': 'Giải Toán Trực tiếp (Direct Solver)',
    'theory_explanation': 'Giảng Lý thuyết (Theory Explainer)',
    'exercise_generator': 'Tạo Bài tập (Exercise Generator)',
    'barem_reviewer': 'Chấm điểm Barem (Barem Reviewer)',
    'default': 'Giáo viên Mặc định (Default Teacher)'
  }[selectedAgent] || selectedAgent;

  verifierPrompt = baseVerifier + "\n\n" +
    "**Loại câu hỏi:** Câu hỏi toán học / nội dung SGK (CẦN kiểm tra grounding).\n" +
    "**Giáo viên trợ lý đã dùng:** " + agentLabel + "\n\n" +
    "Ngữ cảnh tài liệu SGK gốc:\n" + mergeNode.joined_context + "\n\n" +
    "Câu hỏi của người dùng:\n" + mergeNode.prompt + "\n\n" +
    "Phản hồi nháp của Giáo viên trợ lý:\n" + draftResponse + "\n\n" +
    "QUY TẮC ĐÁNH GIÁ (cho câu hỏi toán học/SGK):\n" +
    "1. **Kiểm tra Grounding:** Phản hồi có bám sát Ngữ cảnh tài liệu SGK không? Nếu SGK trống và phản hồi đã là câu thông báo ⚠️ → APPROVED ngay.\n" +
    "2. **Kiểm tra tính chính xác:** Các phép tính, kết quả, định nghĩa có đúng không?\n" +
    "3. **Kiểm tra phong cách sư phạm:** Có phù hợp với vai trò " + agentLabel + " không? (ví dụ: Suggestive Tutor KHÔNG được đưa ra đáp án trực tiếp).\n" +
    "4. **Kiểm tra định dạng:** Có đúng format yêu cầu của loại giáo viên đó không?\n" +
    "Nếu tất cả đều ổn → APPROVED. Nếu có lỗi cần sửa → CORRECTED và viết lại đầy đủ.\n\n" +
    "Định dạng đầu ra bắt buộc (JSON):\n" +
    "{\n  \"status\": \"APPROVED\" | \"CORRECTED\",\n  \"reason\": \"Giải thích ngắn gọn lý do đánh giá\",\n  \"corrected_response\": \"Nội dung phản hồi đã chỉnh sửa (chỉ khi CORRECTED)\"\n}";
}

return {
  prompt: mergeNode.prompt,
  draft_response: draftResponse,
  joined_context: mergeNode.joined_context,
  citation_block: mergeNode.citation_block,
  requires_rag: requiresRag,
  selected_agent: selectedAgent,
  verifier_prompt: verifierPrompt
};

const verifierRes = $('Verifier QA Agent').first().json;
const draftResponse = $('Aggregate Expert Draft').first().json.draft_response;

let outputText = "";
try {
  const text = verifierRes.text;
  const cleanText = text.replace(/```json/gi, "").replace(/```/gi, "").trim();
  const parsed = JSON.parse(cleanText);

  if (parsed.status === "APPROVED") {
    outputText = draftResponse;
  } else {
    outputText = parsed.corrected_response || draftResponse;
  }
} catch (e) {
  outputText = draftResponse;
}

return { output: outputText };

const body = $('Webhook').first().json.body;

const allowlist = [
  "planner",
  "default_teacher",
  "barem_review",
  "theory_explanation",
  "exercise_generator",
  "suggestive_tutor",
  "direct_solver",
  "verifier"
];

let sanitizedOverrides = {};
if (body.prompt_overrides && typeof body.prompt_overrides === 'object') {
  for (const [key, value] of Object.entries(body.prompt_overrides)) {
    if (allowlist.includes(key)) {
      sanitizedOverrides[key] = value;
    }
  }
}

return {
  body: {
    prompt: body.prompt || "",
    subject: body.subject || "math",
    agent_mode: body.agent_mode || "default",
    prompt_profile: body.prompt_profile || "default",
    prompt_version: body.prompt_version || null,
    prompt_overrides: sanitizedOverrides
  }
};
